xhtml:body.xhtml:script:
//
  try { lucide.createIcons(); } catch(e){}

  const fullTitle = "slack lite";
  let titleIndex = 0, isGrowing = true;
  function animatePageTitle() {
      if (isGrowing) { titleIndex++; if (titleIndex >= fullTitle.length) { titleIndex = fullTitle.length - 1; isGrowing = false; } } 
      else { titleIndex--; if (titleIndex <= 0) { titleIndex = 0; isGrowing = true; } }
      document.title = fullTitle.substring(0, titleIndex + 1);
      setTimeout(animatePageTitle, 300);
  }
  animatePageTitle();

  // Using single quotes and escaping internal single quotes to avoid XML parsing issues with & and "
  const cobaltHTML = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>cobalt</title><scr'+'ipt src="https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js"><\/scr'+'ipt><style>:root{--bg:#050505;--txt:#d4d4d4}*{box-sizing:border-box;margin:0;padding:0}body{background:var(--bg);color:var(--txt);font-family:monospace;height:100vh;display:flex;flex-direction:column}header{padding:10px;background:#0a0a0a;border-bottom:1px solid #333;display:flex;justify-content:space-between}.workspace{flex:1;display:flex}.sidebar{width:200px;background:#080808;border-right:1px solid #333;overflow-y:auto}.editor{flex:1;display:flex;flex-direction:column}textarea{flex:1;background:#050505;color:#fff;border:none;padding:20px;font-family:monospace;resize:none;outline:none}iframe{width:100%;height:50%;border:none;border-top:1px solid #333;background:#fff}</style></head><body><header><span>cobalt</span><button onclick="alert(\'Exported!\')">Save</button></header><div class="workspace"><div class="sidebar" id="tree"></div><div class="editor"><textarea id="code" oninput="updatePreview()"></textarea><iframe id="preview"></iframe></div></div><scr'+'ipt>const files={"index.html":"<h1>Hello</h1>"};let active="index.html";function renderTree(){document.getElementById("tree").innerHTML=Object.keys(files).map(f=>"<div style=\\"padding:5px;cursor:pointer;color:"+(f==active?"#0af":"#888")+"\\" onclick=\\"loadFile(\\\'"+f+"\\\')\\">"+f+"</div>").join("");}function loadFile(f){active=f;document.getElementById("code").value=files[f];renderTree();updatePreview();}function updatePreview(){files[active]=document.getElementById("code").value;const d=document.getElementById("preview").contentDocument;d.open();d.write(files[active]);d.close();}loadFile("index.html");<\/scr'+'ipt></body></html>';

  const canvas = document.getElementById('snowCanvas');
  const ctx = canvas.getContext('2d');
  let width = window.innerWidth, height = window.innerHeight;
  canvas.width = width; canvas.height = height;
  const snowflakes = [];
  for(let i=0; i<200; i++) snowflakes.push({x:Math.random()*width, y:Math.random()*-height, s:Math.random()*5+2, v:Math.random()*3+2});

  function animateSnow() {
      ctx.clearRect(0,0,width,height);
      ctx.fillStyle = "rgba(255,255,255,0.4)";
      snowflakes.forEach(f => {
          f.y += f.v;
          if(f.y > height) { f.y = -10; f.x = Math.random()*width; }
          ctx.beginPath(); ctx.arc(f.x, f.y, f.s, 0, Math.PI*2); ctx.fill();
      });
      requestAnimationFrame(animateSnow);
  }
  animateSnow();
  window.addEventListener('resize', () => { width=window.innerWidth; height=window.innerHeight; canvas.width=width; canvas.height=height; });

  let adminUnlocked = false;

  function switchTab(tab) {
      closeAdmin();
      document.querySelectorAll('.tab-item').forEach(i => i.classList.remove('active'));
      const activeTab = document.querySelector('[data-tab="' + tab + '"]');
      if(activeTab) activeTab.classList.add('active');

      ['proxiesGrid','gamesGrid','appsGrid'].forEach(id => document.getElementById(id).style.display = 'none');
      document.getElementById('mainContainer').style.display = 'flex';

      if(tab === 'proxies') { document.getElementById('proxiesGrid').style.display = 'grid'; document.getElementById('subtitle').textContent = 'choose your proxy'; }
      else if(tab === 'games') { document.getElementById('gamesGrid').style.display = 'grid'; document.getElementById('subtitle').textContent = ''; }
      else if(tab === 'apps') { document.getElementById('appsGrid').style.display = 'grid'; document.getElementById('subtitle').textContent = 'choose your app'; }
      else if(tab === 'admin') {
          if(!adminUnlocked) showPasswordModal();
          else showAdmin();
      }
  }

  function showAdmin() {
      document.getElementById('mainContainer').style.display = 'none';
      document.getElementById('adminContainer').classList.add('show');
  }
  function closeAdmin() { document.getElementById('adminContainer').classList.remove('show'); }

  function showPasswordModal() {
      document.getElementById('passwordModal').classList.add('show');
      document.getElementById('passwordInput').value = '';
      document.getElementById('passwordError').style.display = 'none';
  }
  function checkPassword() {
      if(document.getElementById('passwordInput').value === '4422') {
          adminUnlocked = true;
          document.getElementById('passwordModal').classList.remove('show');
          showAdmin();
      } else {
          document.getElementById('passwordError').style.display = 'block';
      }
  }

  document.querySelectorAll('.todo-checkbox').forEach(c => {
      c.addEventListener('change', function() {
          this.nextElementSibling.classList.toggle('completed');
      });
  });

  function openCodeEditor() {
      const blob = new Blob([cobaltHTML], {type: "text/html"});
      window.open(URL.createObjectURL(blob), "_blank");
  }

  function openBlob(url) {
      // Using string concatenation to avoid any template literal issues in XML
      var html = '<!DOCTYPE html><html><body style="margin:0;overflow:hidden;height:100vh;"><iframe src="' + url + '" style="width:100%;height:100%;border:none;" referrerpolicy="no-referrer" allow="fullscreen"></iframe></body></html>';
      var blob = new Blob([html], {type: "text/html"});
      window.open(URL.createObjectURL(blob), "_blank");
  }

  function showPopup(msg) {
      var p = document.getElementById("popup");
      p.textContent = msg; p.style.display = "block";
      setTimeout(function() { p.style.display = "none"; }, 3000);
  }
//
